// Sources: Adzuna (remote-only) + HN 'Who is hiring'. Remotive/RemoteOK/Arbeitnow
// dropped - their APIs returned junk/irrelevant results for this profile.
const KEYWORDS = ($env.JOB_KEYWORDS || 'software engineer').split(',').map((s) => s.trim()).filter(Boolean);
const MAX_AGE_DAYS = parseInt($env.JOB_MAX_AGE_DAYS || '7', 10);
const ADZUNA_ID = $env.ADZUNA_APP_ID;
const ADZUNA_KEY = $env.ADZUNA_APP_KEY;
const ADZUNA_COUNTRY = $env.ADZUNA_COUNTRY || 'us';
const http = this.helpers.httpRequest;
const clip = (s, n = 8000) => (s || '').toString().slice(0, n);

// Adzuna has no remote flag; what_phrase:'remote' restricts to remote-mentioning roles.
async function fetchAdzuna() {
  if (!ADZUNA_ID || !ADZUNA_KEY) return [];
  const out = [];
  for (const kw of KEYWORDS) {
    try {
      const r = await http({
        method: 'GET',
        url: `https://api.adzuna.com/v1/api/jobs/${ADZUNA_COUNTRY}/search/1`,
        qs: { app_id: ADZUNA_ID, app_key: ADZUNA_KEY, results_per_page: 50, what: kw, what_phrase: 'remote', max_days_old: MAX_AGE_DAYS, 'content-type': 'application/json' },
        json: true,
      });
      for (const j of r.results || []) {
        out.push({ source: 'adzuna', title: j.title, company: j.company && j.company.display_name, location: (j.location && j.location.display_name) || 'Remote', url: j.redirect_url, description: clip(j.description), posted: j.created });
      }
    } catch (e) {}
  }
  return out;
}

// HN 'Ask HN: Who is hiring' - founder-posted, often global-remote-friendly.
async function fetchHN() {
  try {
    const story = await http({ method: 'GET', url: 'https://hn.algolia.com/api/v1/search', qs: { query: 'Ask HN: Who is hiring', tags: 'story', hitsPerPage: 1 }, json: true });
    const storyId = story && story.hits && story.hits[0] && story.hits[0].objectID;
    if (!storyId) return [];
    const out = [];
    for (const kw of KEYWORDS) {
      try {
        const c = await http({ method: 'GET', url: 'https://hn.algolia.com/api/v1/search', qs: { tags: `comment,story_${storyId}`, hitsPerPage: 50, query: kw }, json: true });
        for (const h of (c && c.hits) || []) {
          const text = h.comment_text || '';
          if (!text) continue;
          out.push({ source: 'hn', title: kw, company: 'HN Who is hiring', location: 'See post', url: `https://news.ycombinator.com/item?id=${h.objectID}`, description: clip(text), posted: h.created_at });
        }
      } catch (e) {}
    }
    return out;
  } catch (e) { return []; }
}

const sources = await Promise.all([fetchAdzuna(), fetchHN()]);
return sources.flat().filter((j) => j.title && j.url).map((j) => ({ json: j }));

function fnv1a(str) {
  let h = 0x811c9dc5;
  for (let i = 0; i < str.length; i++) {
    h ^= str.charCodeAt(i);
    h = (h + ((h << 1) + (h << 4) + (h << 7) + (h << 8) + (h << 24))) >>> 0;
  }
  return h.toString(16).padStart(8, '0');
}

const seen = new Set();
const out = [];
for (const item of $input.all()) {
  const j = item.json;
  if (!j.title || !j.url) continue;
  const key = `${(j.title||'').toLowerCase().trim()}|${(j.company||'').toLowerCase().trim()}|${j.url}`;
  const hash = fnv1a(key) + fnv1a(key.split('').reverse().join(''));
  if (seen.has(hash)) continue;
  seen.add(hash);
  out.push({ json: { ...j, job_hash: hash } });
}
return out;

// Drop jobs with no tech/AI signal before the expensive per-job scoring loop.
// Word boundaries (\b) so 'ai' doesn't match 'email', 'ml' not 'html', etc.
const RE = /\b(engineer|developer|programmer|frontend|front[-\s]?end|full[-\s]?stack|software|react|next\.?js|vue|angular|svelte|typescript|javascript|node\.?js|node|ai|ml|llm|gen\s?ai|generative|machine\s+learning|gpt|agent|chatbot|large\s+language)\b/i;
const out = [];
for (const item of $input.all()) {
  const j = item.json;
  const hay = (j.title || '') + ' ' + (j.description || '');
  if (RE.test(hay)) out.push({ json: j });
}
return out;
